  const subject = subjectId(number); const questionNo = number - (subject === 'FR' ? 0 : subject === 'TX' ? 40 : 80); const topic = classification(number); const concept = topicNames[topic.primaryTopicId]; const answer = answerMap[number]; const id = `${examMonth}-${subject}-${String(questionNo).padStart(2, '0')}`; const stem = `${extractedStem}${extractedStemAppends[id] || ''}`; const options = extractedOptionOverrides[id] || extractedOptions; const evidence = evidenceFor(stem); const guide = topicGuides[topic.primaryTopicId] || `${concept}의 기준을 적용합니다.`; const correctFocus = optionFocus(options[answer - 1]);
